(()=>{document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".table-scrollable");if(!e.length)return;let t=null;function s(){e.forEach(e=>{const t=e.scrollWidth-e.clientWidth>1;e.classList.toggle("has-horizontal-scroll",t),t||e.classList.remove("is-scrolled")})}function n(){if(t)return;t=requestAnimationFrame(()=>{s(),t=null})}s(),window.addEventListener("resize",n);const o=new ResizeObserver(n);e.forEach(e=>o.observe(e));const i=new MutationObserver(n);e.forEach(e=>{i.observe(e,{childList:!0,subtree:!0})}),e.forEach(e=>{e.addEventListener("scroll",()=>e.classList.add("is-scrolled"),{once:!0,passive:!0})})})})()